/* tests/test_tok.c -- exercises src/tok.c against tests/data/tiny_tok.gguf
 * (a tiny handcrafted gpt2/qwen2 byte-BPE tokenizer, generated by
 * tests/data/make_tok_fixture.py -- see that script's docstring for the
 * exact vocab/merge table and why each token/rule exists). These tests are
 * always-run and have NO dependency on the real 2.5GB model -- the
 * byte-exact gate against the real model is tests/tok_golden.sh
 * (model-gated) plus its corpus roundtrip check.
 *
 * Positive-path assertions run in-process. Every assertion that must
 * observe fatal() uses the spawn-self pattern from tests/test_common.c /
 * tests/test_gguf.c: fatal() calls exit(1) directly, so the only way to
 * observe "did this call fatal the way we expect" from a test that must
 * keep running afterwards is to run that one call in a child process and
 * inspect its exit code + stderr from the outside.
 */
#include "common.h"

#include "gguf.h"
#include "tok.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#ifdef _WIN32
#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#endif

#define FIXTURE(name_) "tests/data/" name_

/* ===========================================================================
 * Shared fixture-opening helper. Deliberately gguf_close()s `f` before
 * returning -- Tok is documented as fully self-contained after
 * tok_from_gguf() returns (src/tok.h), so every test built on this helper
 * also organically checks that Tok doesn't dangle-reference the GgufFile
 * it was built from.
 * ===========================================================================
 */
static Tok* open_tiny_tok(void) {
    GgufFile* f = gguf_open(FIXTURE("tiny_tok.gguf"));
    Tok*      t = tok_from_gguf(f);
    gguf_close(f);
    return t;
}

/* ===========================================================================
 * Child-mode dispatch: `<this binary> --scenario <name>` performs exactly
 * one API call expected to fatal(). No ASSERT_* macros here (test.h isn't
 * included yet -- see its own header comment for why the child-mode
 * function must be defined before that include).
 * ===========================================================================
 */
static int tok_test_child_main(int argc, char** argv) {
    if (argc < 3 || strcmp(argv[1], "--scenario") != 0) {
        fprintf(stderr,
                "test_tok child: bad invocation (want --scenario <name>)\n");
        return 2;
    }
    const char* s = argv[2];

    if (strcmp(s, "bad_model") == 0) {
        GgufFile* f = gguf_open(FIXTURE("tiny_tok_bad_model.gguf"));
        Tok*      t = tok_from_gguf(f);
        tok_free(t);
        gguf_close(f);
    } else if (strcmp(s, "bad_pre") == 0) {
        GgufFile* f = gguf_open(FIXTURE("tiny_tok_bad_pre.gguf"));
        Tok*      t = tok_from_gguf(f);
        tok_free(t);
        gguf_close(f);
    } else if (strcmp(s, "missing_byte") == 0) {
        GgufFile* f = gguf_open(FIXTURE("tiny_tok_missing_byte.gguf"));
        Tok*      t = tok_from_gguf(f);
        tok_free(t);
        gguf_close(f);
    } else if (strcmp(s, "decode_id_out_of_range") == 0) {
        Tok* t = open_tiny_tok();
        char buf[16];
        (void)tok_decode(t, 271 /* vocab_size == first invalid id */, buf,
                          sizeof buf);
        tok_free(t);
    } else if (strcmp(s, "decode_cap_overflow") == 0) {
        Tok* t = open_tiny_tok();
        char buf[3]; /* id 264 (" world") decodes to 6 bytes -- too small */
        (void)tok_decode(t, 264, buf, sizeof buf);
        tok_free(t);
    } else if (strcmp(s, "encode_cap_zero_with_bos") == 0) {
        Tok* t = open_tiny_tok();
        u32  ids[4];
        (void)tok_encode(t, "hello", 5, ids, 0, /*add_special=*/true);
        tok_free(t);
    } else if (strcmp(s, "encode_cap_too_small_for_content") == 0) {
        Tok* t = open_tiny_tok();
        u32  ids[4];
        (void)tok_encode(t, "xz", 2, ids, 1, false); /* 2 unmerged tokens, cap=1 */
        tok_free(t);
    } else {
        fprintf(stderr, "test_tok child: unknown scenario '%s'\n", s);
        return 2;
    }

    printf("test_tok child: scenario '%s' did NOT fatal\n", s);
    return 0;
}
#define TEST_CHILD_MAIN tok_test_child_main
#include "test.h"

/* ===========================================================================
 * Spawn helper -- mirrors tests/test_gguf.c's spawn_scenario /
 * assert_scenario_fatals exactly, including the Windows cmd.exe
 * outer-quote fix (this repo lives under a path with a space).
 * ===========================================================================
 */
static int spawn_scenario(const char* scenario, char* err_buf,
                           size_t err_buf_sz) {
#ifdef _WIN32
    char  exe_path_buf[4096];
    DWORD full_len = GetFullPathNameA(g_test_argv0, (DWORD)sizeof exe_path_buf,
                                       exe_path_buf, NULL);
    if (full_len == 0 || full_len >= sizeof exe_path_buf) {
        fatal("test_tok: GetFullPathNameA failed for '%s'", g_test_argv0);
    }
    const char* exe_path = exe_path_buf;
#else
    const char* exe_path = g_test_argv0;
#endif

    char errfile[4200];
    char inner[8600];
    char cmd[8800];

    snprintf(errfile, sizeof errfile, "%s.%s.stderr", exe_path, scenario);
    snprintf(inner, sizeof inner, "\"%s\" --scenario %s 2>\"%s\"", exe_path,
              scenario, errfile);

#ifdef _WIN32
    snprintf(cmd, sizeof cmd, "\"%s\"", inner); /* extra outer quote pair */
#else
    snprintf(cmd, sizeof cmd, "%s", inner);
#endif

    int rc = system(cmd);

    err_buf[0] = '\0';
    FILE* ef = fopen(errfile, "rb");
    if (ef) {
        size_t n = fread(err_buf, 1, err_buf_sz - 1, ef);
        err_buf[n] = '\0';
        fclose(ef);
        remove(errfile);
    }
    return rc;
}

static void assert_scenario_fatals(const char* scenario,
                                    const char* msg_substr) {
    char errbuf[1024];
    int  rc = spawn_scenario(scenario, errbuf, sizeof errbuf);
    ASSERT_TRUE(rc != 0);
    ASSERT_TRUE(strncmp(errbuf, "fatal: ", 7) == 0);
    if (msg_substr != NULL && strstr(errbuf, msg_substr) == NULL) {
        fprintf(stderr,
                "FAIL %s:%d: scenario '%s': stderr did not contain \"%s\" "
                "(got: %s)\n",
                __FILE__, __LINE__, scenario, msg_substr, errbuf);
        g_test_case_failed = 1;
    }
}

/* ===========================================================================
 * encode() assertion helpers
 * ===========================================================================
 */
static void assert_encode_eq_len(Tok* t, const char* text, u64 len,
                                  const u32* want, u32 want_n) {
    u32 ids[64];
    u32 got_n = tok_encode(t, text, len, ids, 64, false);
    ASSERT_EQ_U32(got_n, want_n);
    u32 n = got_n < want_n ? got_n : want_n;
    for (u32 i = 0; i < n; i++) {
        if (ids[i] != want[i]) {
            fprintf(stderr,
                    "FAIL %s:%d: encode(...)[%u] = %u, want %u\n", __FILE__,
                    __LINE__, i, ids[i], want[i]);
            g_test_case_failed = 1;
        }
    }
}

static void assert_encode_eq(Tok* t, const char* text, const u32* want,
                              u32 want_n) {
    assert_encode_eq_len(t, text, (u64)strlen(text), want, want_n);
}

/* decode(encode(text)) == text, byte-for-byte (task-6a-brief.md B6's
 * roundtrip requirement, "needs no oracle" -- asserted here on the
 * synthetic vocab). Only claimed for well-formed UTF-8 input: canonical
 * re-encoding is a no-op for well-formed bytes (src/tok.c's block comment
 * above utf8_decode_one), so encode/decode is lossless there, but is NOT
 * for overlong/invalid input by design (matching the real oracle) -- see
 * the utf8_overlong_sequence_normalizes_to_canonical_encoding and
 * utf8_invalid_byte_falls_back_to_u_fffd tests above for that boundary. */
static void assert_roundtrip(Tok* t, const char* text, u64 len) {
    u32 ids[64];
    u32 n = tok_encode(t, text, len, ids, 64, false);
    char out[256];
    u32  w = 0;
    for (u32 i = 0; i < n && w < sizeof(out); i++) {
        w += tok_decode(t, ids[i], out + w, (u32)sizeof(out) - w);
    }
    ASSERT_EQ_U32(w, (u32)len);
    if (w == (u32)len) {
        ASSERT_TRUE(memcmp(out, text, len) == 0);
    }
}

/* ===========================================================================
 * Positive-path tests
 * ===========================================================================
 */

TEST(all_256_byte_ids_decode_to_their_own_byte) {
    /* Full cpt_to_byte[] coverage (all 256 base tokens), tested via
       DECODE: vocab_str[id] for id<256 is always a single, validly
       (minimally) UTF-8-encoded remapped codepoint by construction, so
       this direction is unaffected by the encode-side U+FFFD/canonical-
       ization redesign below -- unlike encode, decode never invokes
       utf8_decode_one's fallback path here. */
    Tok* t = open_tiny_tok();
    for (u32 b = 0; b < 256; b++) {
        char out[4];
        u32  wn = tok_decode(t, b, out, 4);
        ASSERT_EQ_U32(wn, 1);
        ASSERT_TRUE((u8)out[0] == (u8)b);
    }
    tok_free(t);
}

TEST(ascii_bytes_roundtrip_via_encode_decode) {
    /* ENCODE-direction coverage is only possible byte-by-byte for
       0x00..0x7F: a LONE byte >=0x80 can never be a structurally complete
       UTF-8 sequence on its own (every multi-byte lead needs continuation
       bytes that aren't there), so it always falls back to U+FFFD now --
       see utf8_invalid_byte_falls_back_to_u_fffd below and the block
       comment above utf8_decode_one in src/tok.c for why. Encode-side
       coverage of high bytes comes from multi-byte sequences instead (the
       'e-acute' test below, and exhaustively from the real oracle corpus
       golden, tests/tok_golden.sh). */
    Tok* t = open_tiny_tok();
    for (u32 b = 0; b < 0x80; b++) {
        char in = (char)(u8)b;
        u32  ids[4];
        u32  n = tok_encode(t, &in, 1, ids, 4, false);
        ASSERT_EQ_U32(n, 1);
        ASSERT_EQ_U32(ids[0], b); /* base tokens are byte-value-ordered */

        char out[4];
        u32  wn = tok_decode(t, ids[0], out, 4);
        ASSERT_EQ_U32(wn, 1);
        ASSERT_TRUE((u8)out[0] == (u8)b);
    }
    tok_free(t);
}

TEST(bpe_merge_chain_builds_hello) {
    Tok* t = open_tiny_tok();
    u32  want[] = {259};
    assert_encode_eq(t, "hello", want, 1);
    tok_free(t);
}

TEST(bpe_merge_leading_space_vs_no_space) {
    Tok* t = open_tiny_tok();
    u32  want_with_space[] = {264};
    assert_encode_eq(t, " world", want_with_space, 1);
    /* No leading space -> base 'w' token, DIFFERENT id than 'Gw' -- the
       "w o" merge was never taught, only "(space)w" (' w') was, so this
       must NOT merge at all. */
    u32 want_no_space[] = {119, 111, 114, 108, 100};
    assert_encode_eq(t, "world", want_no_space, 5);
    tok_free(t);
}

TEST(bpe_tie_break_leftmost_wins_on_equal_rank) {
    Tok* t = open_tiny_tok();
    /* "aaa": both (a,a) pairs (pos0, pos1) match the SAME merge rule (same
       rank) at the first iteration. Leftmost-wins merges pos0 first ->
       [aa,a] -> then (aa,a) merges -> [aaa] = id 266. Rightmost-first
       would instead give [a,aa] -> no rule for (a,aa) in that order ->
       stuck at 2 tokens. This is the discriminating case. */
    u32 want[] = {266};
    assert_encode_eq(t, "aaa", want, 1);
    tok_free(t);
}

TEST(regex_alt3_number_matches_exactly_one_digit) {
    Tok* t = open_tiny_tok();
    /* '1','2' stay SEPARATE fragments (alt3 = \p{N}, not \p{N}+), so the
       "1 2"->"12" rule (id 267) never gets a chance -- it would need both
       digits in the SAME fragment to be adjacent BPE symbols. */
    u32 want[] = {49, 50};
    assert_encode_eq(t, "12", want, 2);
    tok_free(t);
}

TEST(regex_alt4_other_run_is_one_or_more) {
    Tok* t = open_tiny_tok();
    /* "()" DOES merge -- confirms alt4 (unlike alt3) groups BOTH
       punctuation chars into one fragment before BPE ever runs. */
    u32 want[] = {268};
    assert_encode_eq(t, "()", want, 1);
    tok_free(t);
}

TEST(regex_alt4_trailing_crlf_stays_in_fragment) {
    Tok* t = open_tiny_tok();
    /* ")\n" merges -- confirms alt4's trailing [\r\n]* pulls the newline
       into the SAME fragment as the preceding punctuation. */
    u32 want[] = {269};
    assert_encode_eq(t, ")\n", want, 1);
    tok_free(t);
}

TEST(regex_alt1_contraction_priority_over_alt2_greedy) {
    Tok* t = open_tiny_tok();
    /* "'llo": alt1's 'LL' branch matches EXACTLY "'ll" (3 codepoints),
       leaving "o" as a separate fragment. If alt1 didn't exist / weren't
       tried first, alt2's greedy lead+\p{L}+ would swallow all 4 chars as
       ONE fragment, and the "l o"->"lo" rule (id 270) WOULD then fire on
       the last two symbols. Correct (alt1 wins first) => 4 separate
       unmerged bytes; id 270 never appears. */
    u32 want[] = {39, 108, 108, 111};
    assert_encode_eq(t, "'llo", want, 4);
    tok_free(t);
}

TEST(regex_space_run_splits_via_alt6_then_alt2) {
    Tok* t = open_tiny_tok();
    /* mirrors task-6a-brief.md B3's "  leading" -> [220,6388] example: N=2
       spaces before a word -> (N-1) lone space(s) via alt6, then the last
       space + word via alt2. */
    u32 want[] = {32, 264};
    assert_encode_eq(t, "  world", want, 2);
    tok_free(t);
}

TEST(utf8_valid_two_byte_codepoint_is_one_fragment_two_bpe_symbols) {
    Tok* t = open_tiny_tok();
    /* U+00E9 (e-acute), UTF-8 bytes C3 A9: ONE letter codepoint (so ONE
       regex fragment via alt2), but BPE still starts from its TWO raw
       bytes as two separate initial symbols (no merge rule defined for
       C3+A9 here, so they stay separate) -- this is the "classification
       codepoint vs BPE raw byte" distinction src/tok.c's block comment
       above bpe_encode_fragment documents. */
    const u8 eacute[2] = {0xC3, 0xA9};
    u32      want[] = {0xC3, 0xA9};
    assert_encode_eq_len(t, (const char*)eacute, 2, want, 2);
    tok_free(t);
}

/* NOTE on the three tests below: task-6a-brief.md B4 originally described
 * invalid-byte fallback as "decode the byte as its own codepoint
 * 0x00..0xFF". Dispatch-time oracle probing (task-6a-report.md self-
 * review has the full transcript) established this is NOT what
 * llama-tokenize.exe b10037 actually does: it substitutes U+FFFD (not the
 * raw byte value) on structural failure, and is PERMISSIVE about overlong
 * encodings and the surrogate range (accepts them, normalizes to the
 * canonical/minimal encoding of whatever codepoint results). src/tok.c's
 * utf8_decode_one implements the verified behavior; these tests exercise
 * it directly since it's the single most load-bearing deviation from the
 * brief in this implementation. */

TEST(utf8_invalid_byte_falls_back_to_u_fffd) {
    Tok* t = open_tiny_tok();
    /* A lone byte >=0x80 is NEVER a structurally complete sequence by
       itself, so it always substitutes U+FFFD, canonically re-encoded as
       3 bytes (EF BF BD) and BPE'd as 3 unmerged base symbols here (no
       rule defined for those bytes in this fixture). */
    const u8 lone = 0x80;
    u32      want[] = {0xEF, 0xBF, 0xBD};
    assert_encode_eq_len(t, (const char*)&lone, 1, want, 3);
    tok_free(t);
}

TEST(utf8_byte_with_no_valid_lead_pattern_falls_back_to_u_fffd) {
    Tok* t = open_tiny_tok();
    /* 0xFF matches no lead-byte pattern at all (not even structurally) --
       same U+FFFD substitution as any other invalid byte. */
    const u8 invalid = 0xFF;
    u32      want[] = {0xEF, 0xBF, 0xBD};
    assert_encode_eq_len(t, (const char*)&invalid, 1, want, 3);
    tok_free(t);
}

TEST(utf8_overlong_sequence_normalizes_to_canonical_encoding) {
    Tok* t = open_tiny_tok();
    /* C1 81 is a structurally-valid-PATTERN 2-byte sequence (lead 0xC1,
       continuation 0x81) that overlong-encodes codepoint 0x41 ('A'). This
       engine accepts it (no overlong rejection) and canonically
       re-encodes to the single byte 0x41 before BPE -- so it must
       tokenize IDENTICALLY to a lone raw 'A' byte, not as 2 separate
       symbols and not as a fallback. */
    const u8 overlong_A[2] = {0xC1, 0x81};
    u32      want[] = {(u32)'A'};
    assert_encode_eq_len(t, (const char*)overlong_A, 2, want, 1);
    tok_free(t);
}

TEST(utf8_lone_surrogate_sequence_is_structurally_valid_one_fragment) {
    Tok* t = open_tiny_tok();
    /* ED A0 80 is a structurally well-formed 3-byte pattern that decodes
       (permissively -- no surrogate rejection) to U+D800. U+D800's
       canonical 3-byte re-encoding happens to equal its original bytes
       (it isn't overlong, just semantically reserved), so this ends up as
       ONE fragment (single codepoint, category Cs -> classified "other")
       feeding the SAME 3 raw bytes into BPE as 3 unmerged base symbols --
       numerically the same ids a naive byte-by-byte fallback would also
       produce here (no merge rule ties ED/A0/80 together in this
       fixture), but for a different reason: this is one classification
       unit, not three. */
    const u8 surrogate[3] = {0xED, 0xA0, 0x80};
    u32      want[] = {0xED, 0xA0, 0x80};
    assert_encode_eq_len(t, (const char*)surrogate, 3, want, 3);
    tok_free(t);
}

TEST(decode_of_encode_roundtrips_for_well_formed_utf8) {
    Tok* t = open_tiny_tok();
    assert_roundtrip(t, "hello world", 11); /* multi-token: [259, 264] */
    assert_roundtrip(t, "aaa", 3);          /* fully merged: [266] */
    assert_roundtrip(t, "'llo", 4);         /* alt1/alt2 boundary, 4 tokens */
    const u8 eacute[2] = {0xC3, 0xA9};      /* valid 2-byte codepoint */
    assert_roundtrip(t, (const char*)eacute, 2);
    tok_free(t);
}

TEST(add_special_prepends_bos_iff_add_bos_token) {
    Tok* t = open_tiny_tok(); /* fixture sets add_bos_token=true */
    ASSERT_EQ_U32(tok_bos(t), 259);
    ASSERT_EQ_U32(tok_eos(t), 266);

    u32 ids[8];
    u32 n = tok_encode(t, "world", 5, ids, 8, /*add_special=*/true);
    u32 want[] = {259, 119, 111, 114, 108, 100}; /* BOS + unmerged "world" */
    ASSERT_EQ_U32(n, 6);
    for (u32 i = 0; i < 6; i++) ASSERT_EQ_U32(ids[i], want[i]);

    u32 n2 = tok_encode(t, "world", 5, ids, 8, /*add_special=*/false);
    ASSERT_EQ_U32(n2, 5);
    ASSERT_EQ_U32(ids[0], 119);

    tok_free(t);
}

TEST(empty_input_yields_zero_tokens) {
    Tok* t = open_tiny_tok();
    u32  ids[4];
    u32  n = tok_encode(t, "", 0, ids, 4, false);
    ASSERT_EQ_U32(n, 0);
    tok_free(t);
}

